 734: 	uint8_t lenSecondOption = hdrEntry->nrOpt2;
 735: 
 736: 	if (lenSecondOption == 0)
 737: 	{
 738: 		hdrEntry->indexFirstOption = indexOffset;
 739: 		++hdrEntry->nrOpt1;
 740: 		return true;
 741: 	}
 742: 
 743: 	if (static_cast<uint32_t>(indexSecondOption + lenSecondOption + 1) == indexOffset)
 744: 	{
 745: 		++hdrEntry->nrOpt2;
 746: 		return true;
 747: 	}
